import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.BveOjhN0.js";const g=JSON.parse('{"title":"重磅更新","description":"","frontmatter":{"title":"重磅更新"},"headers":[],"relativePath":"zh/00.docs/010.getting-started/001.major-update.md","filePath":"zh/00.docs/010.getting-started/001.major-update.md","lastUpdated":1782620269000}'),r={name:"zh/00.docs/010.getting-started/001.major-update.md"};function i(l,e,s,c,n,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="v5" tabindex="-1">v5 <a class="header-anchor" href="#v5" aria-label="Permalink to &quot;v5&quot;">​</a></h1><h2 id="核心变更" tabindex="-1">核心变更 <a class="header-anchor" href="#核心变更" aria-label="Permalink to &quot;核心变更&quot;">​</a></h2><ol><li><strong>TypeScript 全面重构</strong>：所有 API 均有完整类型定义。</li><li><strong>双模块格式输出</strong>：同时支持 CJS 和 ESM 两种格式。</li><li><strong>Node.js 版本提升</strong>：最低要求 Node.js &gt;= 20.19.0。</li><li><strong>Pino 日志体系</strong>：更强大的日志记录功能。</li><li><strong>Bundle 注册表机制</strong>：启动更快。</li><li><strong>异步控制器加载</strong>：支持 ESM 动态导入，避免同步/异步并发竞争。</li><li><strong>主进程打包</strong>： 主进程代码可以像前端 bundle 。</li><li><strong>构建注册表插件</strong>：复现运行时属性名映射逻辑。</li><li><strong>构建配置全面增强</strong>：新增大量精细控制项。</li><li><strong>构建后独立转译</strong>：对不可打包文件独立转译。</li><li><strong>加密系统升级</strong>： 更安全。</li><li><strong>资源原子化移动</strong>：防止数据丢失。</li><li><strong>ee-bin 全面升级</strong>：新增完整 TypeScript 类型体系。</li><li><strong>EventBus 事件隔离</strong>：生命周期事件优化。</li><li><strong>配置加载 ESM 兼容</strong>：自动解包 <code>__esModule</code> 格式，支持函数/类导出。</li><li><strong>控制器并发安全</strong>：明确保证并发请求间无状态污染。</li><li><strong>Cross 跨进程改进</strong>：优化。</li></ol><h2 id="一、核心架构变更" tabindex="-1">一、核心架构变更 <a class="header-anchor" href="#一、核心架构变更" aria-label="Permalink to &quot;一、核心架构变更&quot;">​</a></h2><h3 id="_1-typescript-全面重构" tabindex="-1">1. TypeScript 全面重构 <a class="header-anchor" href="#_1-typescript-全面重构" aria-label="Permalink to &quot;1. TypeScript 全面重构&quot;">​</a></h3><p>v4 的 <code>ee-core</code> 和 <code>ee-bin</code> 完全由 JavaScript 编写（<code>.js</code>），类型定义仅通过 <code>tsconfig.json</code> 的 <code>emitDeclarationOnly + allowJs</code> 自动生成 <code>.d.ts</code>，源码本身无类型约束。</p><p>v5 对两个核心包进行了<strong>全量 TypeScript 重写</strong>，所有源文件为 <code>.ts</code>，并采用极度严格的编译配置。</p><p><strong>影响</strong>：</p><ul><li>所有 API 均有完整的类型定义，IDE 智能提示大幅提升</li><li>编译期即可捕获隐式 <code>any</code>、未检查索引访问、可选属性误用等常见错误</li><li>ESM 源码中 <code>import</code> 必须带 <code>.js</code> 扩展名（<code>NodeNext</code> 规范）</li></ul><h3 id="_2-双模块格式输出-cjs-esm" tabindex="-1">2. 双模块格式输出（CJS + ESM） <a class="header-anchor" href="#_2-双模块格式输出-cjs-esm" aria-label="Permalink to &quot;2. 双模块格式输出（CJS + ESM）&quot;">​</a></h3><p>v4 仅输出 CommonJS（<code>require(&#39;ee-core&#39;)</code>），v5 同时输出 CJS 和 ESM 两种格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dist/cjs/   → CommonJS (module: CommonJS)</span></span>
<span class="line"><span>dist/esm/   → ESM      (module: NodeNext)</span></span></code></pre></div><p><code>package.json</code> 的 <code>exports</code> 字段为每个子路径提供了条件导出：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;./app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;import&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./dist/esm/app/index.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;require&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./dist/cjs/app/index.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>影响</strong>：</p><ul><li>开发者可在 ESM 项目中直接 <code>import { ElectronEgg } from &#39;ee-core&#39;</code></li><li>CJS 项目继续使用 <code>const { ElectronEgg } = require(&#39;ee-core&#39;)</code></li><li><code>ee-core</code> 的 <code>exports</code> 映射由 <code>scripts/gen-exports.js</code> <strong>自动生成</strong>，新增子路径模块后执行 <code>npm run gen-exports</code> 即可更新，无需手动编辑</li></ul><h3 id="_3-node-js-版本要求提升" tabindex="-1">3. Node.js 版本要求提升 <a class="header-anchor" href="#_3-node-js-版本要求提升" aria-label="Permalink to &quot;3. Node.js 版本要求提升&quot;">​</a></h3><p>v5 要求 <strong>Node.js &gt;= 20.19.0</strong>。</p><hr><h2 id="二、ee-core-功能更新" tabindex="-1">二、ee-core 功能更新 <a class="header-anchor" href="#二、ee-core-功能更新" aria-label="Permalink to &quot;二、ee-core 功能更新&quot;">​</a></h2><h3 id="_4-日志系统-pino-替代-egg-logger" tabindex="-1">4. 日志系统：Pino 替代 egg-logger <a class="header-anchor" href="#_4-日志系统-pino-替代-egg-logger" aria-label="Permalink to &quot;4. 日志系统：Pino 替代 egg-logger&quot;">​</a></h3><p>v4 使用 <code>egg-logger</code>（EggLoggers），日志文件按日追加 <code>-YYYYMMDD</code> 后缀，通过 <code>Object.defineProperty</code> 惰性初始化。</p><p>v5 全面切换至 <strong>Pino</strong> 日志体系：</p><table tabindex="0"><thead><tr><th>特性</th><th>v4 (egg-logger)</th><th>v5 (Pino)</th></tr></thead><tbody><tr><td>日志库</td><td>egg-logger</td><td>pino + pino-roll + pino-pretty</td></tr><tr><td>滚动策略</td><td>按日追加后缀</td><td>pino-roll：按日/按小时滚动</td></tr><tr><td>开发输出</td><td>自定义格式</td><td>pino-pretty：可配置颜色、深度、时间戳</td></tr><tr><td>时区</td><td>UTC 固定</td><td>IANA 时区支持（如 <code>Asia/Shanghai</code>）</td></tr><tr><td>日志脱敏</td><td>无</td><td>Pino redaction（字段遮蔽）</td></tr><tr><td>自定义级别</td><td>固定</td><td>可配置自定义 level</td></tr><tr><td>调用风格</td><td>标准方法调用</td><td>Proxy 包装：支持 <code>{obj, msg}</code>、printf <code>(&#39;count: %d&#39;, 42)</code>、拼接 <code>(&#39;msg:&#39;, val)</code> 三种风格</td></tr><tr><td>安全模式</td><td>无</td><td>safe 模式防止序列化崩溃</td></tr></tbody></table><p><strong>影响</strong>：</p><ul><li>日志配置项从 <code>config.logger</code> 的 egg-logger 格式迁移为 pino 格式</li><li><code>coreLogger</code>、<code>logger</code>、<code>errorLogger</code> 三个实例保留，但底层实现完全不同</li><li>开发者需更新自定义日志配置</li></ul><h3 id="_5-bundle-模式-注册表机制" tabindex="-1">5. Bundle 模式：注册表机制 <a class="header-anchor" href="#_5-bundle-模式-注册表机制" aria-label="Permalink to &quot;5. Bundle 模式：注册表机制&quot;">​</a></h3><p>这是 v5 最核心的架构新增。v4 在运行时通过 <code>globby</code> 扫描文件系统加载控制器和配置，打包后的应用也依赖文件系统路径。</p><p><strong>影响</strong>：</p><ul><li>打包后所有控制器和配置被注册到全局变量，无需文件系统扫描，启动更快</li><li>惰性 getter 避免初始化顺序问题——控制器不会在注册阶段就执行</li><li>开发模式（未 bundle）自动回退到文件系统扫描，行为与 v4 一致</li><li><code>process.env.EE_BUNDLED = &quot;true&quot;</code> 标识 bundle 模式</li></ul><h3 id="_6-异步控制器加载" tabindex="-1">6. 异步控制器加载 <a class="header-anchor" href="#_6-异步控制器加载" aria-label="Permalink to &quot;6. 异步控制器加载&quot;">​</a></h3><p>v4 的 <code>ControllerLoader</code> 仅支持同步 <code>require()</code> 加载。v5 新增异步加载路径：</p><ul><li><code>Application.runAsync()</code> → <code>loadControllerAsync()</code> → <code>FileLoader.parseAsync()</code> → <code>import()</code> 动态加载</li><li>加载过程有 <code>loading</code> 标志防止同步/异步并发竞争</li></ul><p><strong>影响</strong>：</p><ul><li>ESM 项目可使用 <code>runAsync()</code> 确保异步模块正确加载</li><li>异步加载模式下控制器文件可以是 ESM 格式</li></ul><h3 id="_7-ipc-双模型" tabindex="-1">7. IPC 双模型 <a class="header-anchor" href="#_7-ipc-双模型" aria-label="Permalink to &quot;7. IPC 双模型&quot;">​</a></h3><p>v5 明确了 <strong>IPC 双模型</strong>：</p><table tabindex="0"><thead><tr><th>模型</th><th>渲染器调用</th><th>主进程注册</th><th>特性</th></tr></thead><tbody><tr><td>send/on</td><td><code>webContents.send</code> / <code>ipcRenderer.send</code></td><td><code>ipcMain.on</code></td><td>同步，<code>event.returnValue</code> + <code>event.reply</code></td></tr><tr><td>invoke/handle</td><td><code>ipcRenderer.invoke</code></td><td><code>ipcMain.handle</code></td><td>异步，Promise 返回值，<strong>推荐使用</strong></td></tr></tbody></table><p>错误传播新增 <code>{__EE_ERROR__: true, message}</code> 结构化标记。</p><h3 id="_8-http-服务-koa-中间件链规范化" tabindex="-1">8. HTTP 服务：Koa 中间件链规范化 <a class="header-anchor" href="#_8-http-服务-koa-中间件链规范化" aria-label="Permalink to &quot;8. HTTP 服务：Koa 中间件链规范化&quot;">​</a></h3><p>v5 对中间件链进行了<strong>明确排序</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>errorHandler → preMiddleware → CORS → koa-body → dispatch → postMiddleware</span></span></code></pre></div><p>新增 <code>koaConfig</code> 配置节，开发者可独立配置 <code>preMiddleware</code>、<code>postMiddleware</code> 数组。</p><h3 id="_9-子进程配置传递-argv-替代文件系统" tabindex="-1">9. 子进程配置传递：argv 替代文件系统 <a class="header-anchor" href="#_9-子进程配置传递-argv-替代文件系统" aria-label="Permalink to &quot;9. 子进程配置传递：argv 替代文件系统&quot;">​</a></h3><p>v5 改为通过 <strong><code>process.argv[2]</code></strong> 传递 <code>eeConfig</code>（JSON 字符化后由 <code>JobProcess</code> 注入），子进程内 <code>setConfig()</code> 解析并缓存，无需读取文件系统。</p><p><strong>影响</strong>：</p><ul><li>打包后的应用中 <code>child_process.fork()</code> 场景更可靠</li><li>子进程不再依赖配置文件路径</li></ul><h3 id="_10-端口分配-双级锁机制" tabindex="-1">10. 端口分配：双级锁机制 <a class="header-anchor" href="#_10-端口分配-双级锁机制" aria-label="Permalink to &quot;10. 端口分配：双级锁机制&quot;">​</a></h3><p>v5 引入 <strong>old + young 双级锁集合</strong>（15 秒轮转），防止并发进程抢占同一端口。</p><p>同时检测所有本地网络接口，避免分配已被占用的端口。</p><h3 id="_11-systemsleep-真正同步阻塞" tabindex="-1">11. systemSleep：真正同步阻塞 <a class="header-anchor" href="#_11-systemsleep-真正同步阻塞" aria-label="Permalink to &quot;11. systemSleep：真正同步阻塞&quot;">​</a></h3><p>v5 新增 <code>systemSleep(ms)</code> 工具函数，使用 <code>Atomics.wait</code> + <code>SharedArrayBuffer</code> 实现真正同步阻塞（不占用 CPU），带 busy-wait 回退。</p><h3 id="_12-零-lodash-依赖" tabindex="-1">12. 零 lodash 依赖 <a class="header-anchor" href="#_12-零-lodash-依赖" aria-label="Permalink to &quot;12. 零 lodash 依赖&quot;">​</a></h3><p>v5 全面去除了以下 npm 依赖，用自研轻量实现替代：</p><table tabindex="0"><thead><tr><th>v4 依赖</th><th>v5 替代</th><th>位置</th></tr></thead><tbody><tr><td>lodash.merge</td><td><code>extend.ts</code>（自研深合并）</td><td>ee-core, ee-bin 共用</td></tr><tr><td>chalk</td><td>ANSI 转义码轻量实现</td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>is-type-of</td><td><code>is.function()</code> / <code>is.class()</code></td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>fs-extra</td><td><code>copyDirSync()</code> 自实现</td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>debug</td><td><code>createDebug()</code> 环境变量驱动</td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>egg-logger</td><td>pino 体系</td><td>ee-core <code>log/</code></td></tr><tr><td>adm-zip</td><td>compressing</td><td>ee-bin <code>incrUpdater</code></td></tr></tbody></table><p><strong>影响</strong>：</p><ul><li>包体积和安全风险大幅降低</li></ul><hr><h2 id="三、ee-bin-功能更新" tabindex="-1">三、ee-bin 功能更新 <a class="header-anchor" href="#三、ee-bin-功能更新" aria-label="Permalink to &quot;三、ee-bin 功能更新&quot;">​</a></h2><h3 id="_13-构建注册表插件-核心新增" tabindex="-1">13. 构建注册表插件（核心新增） <a class="header-anchor" href="#_13-构建注册表插件-核心新增" aria-label="Permalink to &quot;13. 构建注册表插件（核心新增）&quot;">​</a></h3><p>v4 的 ee-bin 没有 esbuild 插件机制，控制器和配置文件直接打包进 main.js（或 copy 模式原样复制）。</p><p>v5 新增 <strong><code>bundle_registry_plugin.ts</code></strong>，这是 v5 打包架构的关键组件：</p><ul><li>虚拟模块 <code>app:controller-registry</code>：扫描控制器目录，生成注册表</li><li>虚拟模块 <code>app:config-registry</code>：扫描配置目录，生成注册表</li><li>虚拟模块 <code>app:bundle-entry</code>：按序加载注册表 + main.js 的入口</li></ul><p><code>computeProperties()</code> 函数复现了 ee-core 的 <code>defaultCamelize(caseStyle: &#39;lower&#39;)</code> 逻辑，确保构建时和运行时的属性名映射一致。</p><h3 id="_14-构建配置全面增强" tabindex="-1">14. 构建配置全面增强 <a class="header-anchor" href="#_14-构建配置全面增强" aria-label="Permalink to &quot;14. 构建配置全面增强&quot;">​</a></h3><p>v5 的 <code>build.electron</code>（<code>BundleConfig</code> 类型）新增大量精细控制项：</p><table tabindex="0"><thead><tr><th>配置项</th><th>v4</th><th>v5</th><th>说明</th></tr></thead><tbody><tr><td><code>external</code></td><td>无</td><td>✅</td><td>用户自定义外部包</td></tr><tr><td><code>sourcemap</code></td><td>false (固定)</td><td><code>false</code> → 自动逻辑</td><td>dev→inline, prod→off；可显式设 <code>inline</code>/<code>external</code></td></tr><tr><td><code>minify</code></td><td>无</td><td>✅</td><td>生产压缩</td></tr><tr><td><code>drop</code></td><td>无</td><td>✅</td><td>移除 <code>console</code>/<code>debugger</code></td></tr><tr><td><code>keepNames</code></td><td>无</td><td>✅</td><td>压缩时保留函数/类名</td></tr><tr><td><code>legalComments</code></td><td>无</td><td>✅</td><td><code>inline</code>/<code>eof</code>/<code>none</code></td></tr><tr><td><code>define</code></td><td>无</td><td>✅</td><td>编译期常量注入</td></tr><tr><td><code>copy</code></td><td>无</td><td>✅</td><td>额外文件/目录复制</td></tr><tr><td><code>format</code></td><td>无</td><td>✅</td><td><code>cjs</code>/<code>esm</code>；默认 <code>cjs</code></td></tr><tr><td>框架外部包</td><td>无明确列表</td><td>✅</td><td>ee-core, ee-bin, electron, better-sqlite3, proxy-agent, pino-roll, pino-pretty</td></tr></tbody></table><p><strong>影响</strong>：</p><ul><li>生产构建可精细控制 sourcemap、压缩、常量注入等</li><li><code>sourcemap: false</code> 不再是&quot;永远关闭&quot;，而是&quot;自动按环境决定&quot;</li><li><code>format: &#39;esm&#39;</code> 模式要求业务代码（控制器、服务、配置）全部 ESM 兼容</li></ul><h3 id="_15-构建后处理-独立文件转译" tabindex="-1">15. 构建后处理：独立文件转译 <a class="header-anchor" href="#_15-构建后处理-独立文件转译" aria-label="Permalink to &quot;15. 构建后处理：独立文件转译&quot;">​</a></h3><p>v5 的 bundle 模式在打包后，对不可打包的文件（<code>preload/bridge.js</code>、<code>jobs/</code> 目录、用户 <code>copy</code> 配置项）执行<strong>独立 esbuild 转译</strong>：</p><ul><li>脚本文件（<code>.js</code>/<code>.ts</code>）以 <code>bundle: false</code> 编译为 Node 可加载的 CJS <code>.js</code>，保留运行时 <code>require()</code> 调用</li><li>非脚本文件原样复制</li><li>所有转译使用 <code>_resolveBaseBuildOptions()</code> 共享设置，保证与主包格式一致</li></ul><p><strong>影响</strong>：</p><ul><li><code>preload/bridge.js</code> 和 <code>jobs/</code> 文件在打包环境下也能正确运行</li><li>不再需要手动处理 <code>child_process.fork()</code> 路径问题</li></ul><h3 id="_16-加密系统升级" tabindex="-1">16. 加密系统升级 <a class="header-anchor" href="#_16-加密系统升级" aria-label="Permalink to &quot;16. 加密系统升级&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;"><br></th><th>特性</th><th>v4</th><th>v5</th></tr></thead><tbody><tr><td style="text-align:left;"><code>entryFiles</code></td><td>无</td><td>✅</td><td>入口文件（如 <code>main.js</code>）编译为 <code>.jsc</code> 后覆写 <code>.js</code> 为 bytenode loader shell</td></tr><tr><td style="text-align:left;"><code>bytecodeOptions</code></td><td>固定 <code>electron: true</code></td><td>✅</td><td>可配置 bytenode 编译参数</td></tr><tr><td style="text-align:left;">安全校验</td><td>无</td><td>✅</td><td>编译后验证 <code>.jsc</code> 存在才删除 <code>.js</code>；不存在则抛错保留源文件</td></tr><tr><td style="text-align:left;"><code>silent</code> 模式</td><td>无</td><td>✅</td><td>隐藏 javascript-obfuscator 的 Pro 广告输出</td></tr><tr><td style="text-align:left;"><code>cleanFiles</code></td><td>无</td><td>✅</td><td>指定需要清理的加密产物</td></tr><tr><td style="text-align:left;"><code>encryptDir</code></td><td>无</td><td>✅</td><td>自定义加密输出目录</td></tr></tbody></table><h3 id="_17-资源移动-原子化操作" tabindex="-1">17. 资源移动：原子化操作 <a class="header-anchor" href="#_17-资源移动-原子化操作" aria-label="Permalink to &quot;17. 资源移动：原子化操作&quot;">​</a></h3><p>v5 的 <code>move.ts</code> 改为 <strong>原子化操作</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>备份目标 → .bak → 复制源到目标 → 删除备份</span></span></code></pre></div><p>复制失败时恢复 <code>.bak</code>，防止数据丢失。</p><h3 id="_18-其他-ee-bin-变更" tabindex="-1">18. 其他 ee-bin 变更 <a class="header-anchor" href="#_18-其他-ee-bin-变更" aria-label="Permalink to &quot;18. 其他 ee-bin 变更&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>v4</th><th>v5</th></tr></thead><tbody><tr><td>esbuild</td><td>0.21.5</td><td>0.28</td></tr><tr><td>commander</td><td>11.0.0</td><td>14</td></tr><tr><td>压缩库</td><td>adm-zip</td><td>compressing</td></tr><tr><td>测试框架</td><td>无</td><td>Vitest（覆盖率 90%/85%）</td></tr><tr><td><code>pargv.js</code></td><td>minimist 风格解析器</td><td>保留但重构为 TS</td></tr><tr><td>TypeScript 类型</td><td>无</td><td>完整 <code>BinConfig</code> 类型体系</td></tr><tr><td>配置加载</td><td><code>.js/.cjs/.ts/.json/.json5</code></td><td>同上 + ESM 默认导出解包 + 函数/类配置工厂</td></tr></tbody></table><hr><h2 id="四、通用变更" tabindex="-1">四、通用变更 <a class="header-anchor" href="#四、通用变更" aria-label="Permalink to &quot;四、通用变更&quot;">​</a></h2><h3 id="_19-eventbus-改进" tabindex="-1">19. EventBus 改进 <a class="header-anchor" href="#_19-eventbus-改进" aria-label="Permalink to &quot;19. EventBus 改进&quot;">​</a></h3><p>v5 的 <code>EventBus</code> 将生命周期事件和自定义事件分为两个独立内部 Map：</p><ul><li><strong>生命周期事件</strong>（<code>register</code>/<code>emitLifecycle</code>）：重复注册会<strong>覆盖并警告</strong>，异步错误<strong>重新抛出</strong></li><li><strong>自定义事件</strong>（<code>on</code>/<code>emit</code>）：异步错误<strong>捕获并记录日志</strong>，不中断流程</li></ul><p>v4 的 EventBus 两种事件共用同一机制，无覆盖警告。</p><h3 id="_20-配置加载-esm-兼容" tabindex="-1">20. 配置加载 ESM 兼容 <a class="header-anchor" href="#_20-配置加载-esm-兼容" aria-label="Permalink to &quot;20. 配置加载 ESM 兼容&quot;">​</a></h3><p>v5 的 <code>loadFile()</code> / <code>loadFileAsync()</code> 新增 ESM 兼容：</p><ul><li>自动解包 <code>{__esModule: true, default: fn}</code> 格式</li><li>配置文件导出函数时自动调用（传入 <code>appInfo</code>）</li><li>配置文件导出类时直接使用（不调用）</li><li>异步版本使用 <code>import()</code> 加载</li></ul><h3 id="_21-控制器并发安全" tabindex="-1">21. 控制器并发安全 <a class="header-anchor" href="#_21-控制器并发安全" aria-label="Permalink to &quot;21. 控制器并发安全&quot;">​</a></h3><p>v5 明确标注：每个 middleware 调用<strong>创建新的控制器实例</strong>，确保并发请求间无状态污染。类型系统也在 <code>ControllerLoader</code> 中强化了这一约束。</p><h3 id="_22-cross-跨进程管理改进" tabindex="-1">22. Cross 跨进程管理改进 <a class="header-anchor" href="#_22-cross-跨进程管理改进" aria-label="Permalink to &quot;22. Cross 跨进程管理改进&quot;">​</a></h3><p>v5 的 <code>Cross</code> 类在 <code>run()</code> 时新增：</p><ul><li>动态端口分配（双级锁机制）</li><li>重名服务自动追加 pid 后缀避免冲突</li></ul><hr><h2 id="五、迁移注意事项" tabindex="-1">五、迁移注意事项 <a class="header-anchor" href="#五、迁移注意事项" aria-label="Permalink to &quot;五、迁移注意事项&quot;">​</a></h2><h3 id="必须调整" tabindex="-1">必须调整 <a class="header-anchor" href="#必须调整" aria-label="Permalink to &quot;必须调整&quot;">​</a></h3><ol><li><strong>Node.js 版本</strong>：确保 &gt;= 20.19.0</li><li><strong>日志配置</strong>：从 egg-logger 格式迁移为 pino 格式（<code>pino-roll</code> 滚动、<code>pino-pretty</code> 输出等）</li><li><strong>ESM import 扩展名</strong>：ee-core 源码中的 <code>import</code> 必须带 <code>.js</code>（NodeNext 规范）</li></ol><h3 id="建议调整" tabindex="-1">建议调整 <a class="header-anchor" href="#建议调整" aria-label="Permalink to &quot;建议调整&quot;">​</a></h3><ol><li><strong>构建配置</strong>：利用新增的 <code>minify</code>、<code>drop</code>、<code>define</code>、<code>sourcemap</code> 自动逻辑等提升生产包质量</li><li><strong>加密配置</strong>：新增 <code>entryFiles</code>、<code>bytecodeOptions</code>、<code>silent</code> 等选项，可更精细控制加密行为</li><li><strong>异步控制器</strong>：ESM 项目使用 <code>runAsync()</code> + <code>loadControllerAsync()</code></li></ol><h3 id="无需调整" tabindex="-1">无需调整 <a class="header-anchor" href="#无需调整" aria-label="Permalink to &quot;无需调整&quot;">​</a></h3><ul><li>开发模式下控制器/配置加载回退到文件系统扫描，行为与 v4 一致</li><li><code>ElectronEgg</code> 入口类、<code>Application</code> 单例、启动流程顺序未变</li><li>三通道通信（Socket.IO、HTTP、IPC）架构不变</li><li>子进程（ChildJob、ChildPoolJob）API 不变</li><li>SqliteStorage API 不变</li></ul>`,104)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
